import { useLocalSearchParams, useRouter } from 'expo-router';
import { useState } from 'react';
import { Alert, Image, ImageBackground, Pressable, ScrollView, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';
import { C, S, Button, Card, Divider, Icon, Stat, Tag } from '../ui';
import { discussions, farmer, initialTasks, marketPrices, navItems, schemes, screenMeta, weather } from '../data';
import farmerAvatar from '../../assets/farmer-avatar.png';
import farmerHero from '../../assets/farmer-field-hero.png';
import riceLeafPhoto from '../../assets/rice-leaf-blight.png';

const menu = [
  ['dashboard', 'Home', 'view-dashboard-outline'], ['farm-plan', 'Farm plan', 'calendar-check-outline'],
  ['disease', 'Crop scan', 'leaf'], ['weather', 'Weather', 'weather-partly-cloudy'],
  ['map', 'Farm health map', 'map-outline'], ['yield', 'Yield forecast', 'chart-box-outline'],
  ['market', 'Market prices', 'currency-inr'], ['assistant', 'Ask AI', 'robot-outline'],
  ['schemes', 'Govt schemes', 'bank-outline'], ['notifications', 'Notifications', 'bell-outline'],
  ['community', 'Community', 'account-group-outline'], ['profile', 'My profile', 'account-circle-outline'],
];

export default function ScreenRoute() {
  const params = useLocalSearchParams<{ screen: string }>();
  const screen = params.screen || 'dashboard';
  const router = useRouter();
  const { width } = useWindowDimensions();
  const desktop = width >= 900;
  const [tasks, setTasks] = useState(initialTasks.map(t => ({ ...t, done: false })));
  const [chat, setChat] = useState([{ from: 'farmer', text: 'Why are my leaves turning yellow?' }, { from: 'ai', text: 'Yellow leaves can have a few causes: nitrogen deficiency, water stress, root disease, or over-watering. A clear crop photo will help narrow it down.' }]);
  const [draft, setDraft] = useState('');
  const [scanned, setScanned] = useState(false);
  const [filter, setFilter] = useState('All');
  const [locationMode, setLocationMode] = useState('Satellite');

  const go = (route: string) => router.push(`/${route}` as any);
  const meta = screenMeta[screen] || screenMeta.more;
  const doneCount = tasks.filter(t => t.done).length;
  const showAppShell = !['splash', 'login', 'profile-setup', 'closing'].includes(screen);

  const sendChat = (text = draft) => {
    const clean = text.trim(); if (!clean) return;
    setChat(old => [...old, { from: 'farmer', text: clean }, { from: 'ai', text: 'For your paddy in Anakapalle, start by checking the affected leaves and field moisture. If you share a photo, I can help assess the symptoms. This is sample guidance in the prototype.' }]);
    setDraft('');
  };

  return (
    <View style={styles.root}>
      {showAppShell && desktop ? <View style={styles.sidebar}>
        <Pressable onPress={() => go('dashboard')} style={styles.brand}><View style={styles.brandMark}><Icon name="sprout" color={C.white} size={23} /></View><View><Text style={styles.brandName}>Kisaan Mitra</Text><Text style={styles.brandSub}>AI FARMING COMPANION</Text></View></Pressable>
        <Text style={styles.sideLabel}>YOUR FARM</Text>
        {menu.map(([id, label, icon]) => <SideLink key={id} id={id} label={label} icon={icon} active={screen === id} onPress={go} />)}
        <View style={styles.sidebarBottom}><Text style={{ color: '#c5d8c8', fontSize: 12 }}>🌱  Growing together</Text><Text style={{ color: '#a8c4ac', fontSize: 11, marginTop: 5 }}>Sample farm · {farmer.village}</Text></View>
      </View> : null}
      <View style={styles.main}>
        {showAppShell ? <View style={styles.topbar}>
          {!desktop ? <Pressable onPress={() => go('dashboard')} style={styles.brandMarkSmall}><Icon name="sprout" color={C.white} size={19} /></Pressable> : <Text style={styles.crumb}>FARM OVERVIEW <Text style={{ color: C.green }}> / {meta.title.toUpperCase()}</Text></Text>}
          {!desktop ? <Text style={styles.brandMobile}>Kisaan Mitra <Text style={{ color: C.green }}>AI</Text></Text> : null}
          <View style={{ flex: 1 }} />
          <Pressable onPress={() => go('notifications')} style={styles.bell}><Icon name="bell-outline" size={20} color={C.ink} /><View style={styles.bellDot} /></Pressable>
          {desktop ? <Pressable onPress={() => go('profile')} style={styles.avatar}><Text style={{ color: C.greenDark, fontWeight: '800' }}>RK</Text></Pressable> : null}
        </View> : null}

        <ScrollView contentContainerStyle={[S.content, desktop && styles.desktopContent, !showAppShell && styles.onboardContent]} showsVerticalScrollIndicator={false}>
          {showAppShell ? <View style={styles.pageHeading}><View style={{ flex: 1 }}><Text style={S.title}>{meta.title}</Text><Text style={S.subtitle}>{meta.subtitle}</Text></View>{desktop ? <Tag>DEMO DATA</Tag> : null}</View> : null}
          <View style={styles.screenBody}>
            {screen === 'splash' && <Splash go={go} />}
            {screen === 'login' && <Login go={go} />}
            {screen === 'profile-setup' && <ProfileSetup go={go} />}
            {screen === 'dashboard' && <Dashboard go={go} desktop={desktop} />}
            {screen === 'farm-plan' && <FarmPlan tasks={tasks} setTasks={setTasks} doneCount={doneCount} />}
            {screen === 'disease' && <Disease scanned={scanned} setScanned={setScanned} go={go} />}
            {screen === 'weather' && <WeatherScreen go={go} />}
            {screen === 'map' && <MapScreen mode={locationMode} setMode={setLocationMode} go={go} />}
            {screen === 'yield' && <YieldScreen go={go} />}
            {screen === 'market' && <MarketScreen go={go} />}
            {screen === 'assistant' && <Assistant chat={chat} draft={draft} setDraft={setDraft} send={sendChat} />}
            {screen === 'schemes' && <Schemes />}
            {screen === 'notifications' && <Notifications filter={filter} setFilter={setFilter} />}
            {screen === 'community' && <Community />}
            {screen === 'profile' && <Profile go={go} />}
            {screen === 'more' && <More go={go} />}
            {screen === 'closing' && <Closing go={go} />}
            {!screenMeta[screen] && <More go={go} />}
          </View>
          <Text style={styles.disclaimer}>Prototype with sample data · Advice should be confirmed with a local agriculture expert.</Text>
        </ScrollView>
        {showAppShell && !desktop ? <View style={styles.bottomNav}>{navItems.map(item => <Pressable key={item.route} onPress={() => go(item.route)} style={styles.bottomItem}><Icon name={item.icon === 'home' ? 'home-variant' : item.icon === 'scan' ? 'line-scan' : item.icon === 'mic' ? 'microphone-outline' : item.icon === 'check' ? 'checkbox-marked-circle-outline' : 'dots-horizontal'} size={20} color={screen === item.route ? C.green : C.muted} /><Text style={[styles.bottomText, screen === item.route && { color: C.green, fontWeight: '800' }]}>{item.label}</Text></Pressable>)}</View> : null}
      </View>
    </View>
  );
}

function SideLink({ id, label, icon, active, onPress }: { id: string; label: string; icon: string; active: boolean; onPress: (route: string) => void }) {
  return <Pressable onPress={() => onPress(id)} style={[styles.sideLink, active && styles.sideLinkActive]}><Icon name={icon} size={18} color={active ? '#f4fff3' : '#bed0c0'} /><Text style={[styles.sideLinkText, active && { color: C.white, fontWeight: '800' }]}>{label}</Text>{id === 'notifications' ? <View style={styles.sideBadge}><Text style={{ color: C.white, fontSize: 10, fontWeight: '800' }}>2</Text></View> : null}</Pressable>;
}

function Splash({ go }: { go: (s: string) => void }) {
  return <View style={styles.splash}>
    <View style={styles.splashLogo}><Icon name="sprout" size={40} color={C.green} /></View>
    <Text style={styles.splashBrand}>Kisaan Mitra AI</Text><Text style={styles.splashTagline}>Smarter farms. Brighter tomorrows.</Text>
    <ImageBackground source={farmerHero} resizeMode="cover" style={styles.heroPhoto} imageStyle={{ borderRadius: 24 }}><View style={styles.heroPhotoCaption}><Text style={styles.heroCaptionTitle}>Good things grow here.</Text><Text style={styles.heroCaptionBody}>A farming companion, rooted in your everyday.</Text></View></ImageBackground>
    <View style={styles.splashPerks}><Text style={styles.perk}>✦  AI insights</Text><Text style={styles.perk}>✦  Better yields</Text><Text style={styles.perk}>✦  Happier farmers</Text></View>
    <Button title="Get started" icon="arrow-right" onPress={() => go('login')} style={{ width: '100%', maxWidth: 360, marginTop: 22 }} />
    <Pressable onPress={() => Alert.alert('Language', 'English selected for this prototype.')} style={{ padding: 12 }}><Text style={S.muted}>Language: English  ⌄</Text></Pressable>
  </View>;
}

function Login({ go }: { go: (s: string) => void }) {
  return <View style={styles.onboardWrap}><View style={styles.onboardIcon}><Icon name="sprout" size={30} color={C.green} /></View><Text style={[S.title, { textAlign: 'center' }]}>Welcome to Kisaan Mitra AI</Text><Text style={[S.subtitle, { textAlign: 'center', marginBottom: 24 }]}>Let’s grow together</Text>
    <Card style={{ width: '100%', maxWidth: 430 }}><Text style={styles.inputLabel}>Mobile number</Text><View style={styles.phoneInput}><Text style={{ color: C.ink, fontWeight: '700' }}>+91</Text><TextInput placeholder="Enter your number" keyboardType="phone-pad" style={styles.input} /></View><Button title="Send OTP" icon="message-text-outline" onPress={() => go('profile-setup')} style={{ marginTop: 14 }} /><Text style={[S.muted, { textAlign: 'center', marginVertical: 16 }]}>or continue with</Text><Button title="Continue with Google" secondary icon="google" onPress={() => go('profile-setup')} /><Button title="Continue with WhatsApp" secondary icon="whatsapp" onPress={() => go('profile-setup')} style={{ marginTop: 10 }} /></Card>
    <Text style={[S.muted, { textAlign: 'center', marginTop: 18, maxWidth: 380 }]}>By continuing, you agree to our Terms and Privacy Policy. Sign-in is simulated in this prototype.</Text></View>;
}

function ProfileSetup({ go }: { go: (s: string) => void }) {
  return <View style={styles.onboardWrap}><Text style={[S.title, { textAlign: 'center' }]}>Tell us about your farm</Text><Text style={[S.subtitle, { textAlign: 'center', marginBottom: 20 }]}>This helps us personalize recommendations.</Text><Card style={{ width: '100%', maxWidth: 500 }}>
    <InputRow label="Full name" value={farmer.name} /><InputRow label="State" value={farmer.state + '  ⌄'} /><InputRow label="District" value={farmer.district + '  ⌄'} /><InputRow label="Village" value={farmer.village} /><View style={{ flexDirection: 'row', gap: 12 }}><View style={{ flex: 1 }}><InputRow label="Farm area" value="10 acres" /></View><View style={{ flex: 1 }}><InputRow label="Main crop" value="Paddy  ⌄" /></View></View><Card style={styles.locationCard}><Icon name="map-marker" size={18} color={C.green} /><View style={{ flex: 1 }}><Text style={styles.inputLabel}>Farm location</Text><Text style={S.muted}>Anakapalle, Andhra Pradesh</Text></View><Text style={{ fontSize: 22 }}>📍</Text></Card><Button title="Continue to my farm" icon="arrow-right" onPress={() => go('dashboard')} style={{ marginTop: 16 }} />
  </Card></View>;
}

function InputRow({ label, value }: { label: string; value: string }) {
  return <View style={{ marginBottom: 13 }}><Text style={styles.inputLabel}>{label}</Text><View style={styles.field}><Text style={S.body}>{value}</Text></View></View>;
}

function Dashboard({ go, desktop }: { go: (s: string) => void; desktop: boolean }) {
  return <View style={styles.stack}>
    <Card style={styles.welcomeCard}><View style={{ flex: 1 }}><Tag>YOUR FARM TODAY</Tag><Text style={{ color: C.white, fontSize: 23, fontWeight: '800', marginTop: 13 }}>Good morning, Ramesh!</Text><Text style={{ color: '#d6e8d7', fontSize: 13, marginTop: 5 }}>{farmer.village} · {farmer.crop} · {farmer.area}</Text><Button title="Open today’s farm plan" secondary icon="arrow-right" onPress={() => go('farm-plan')} style={{ marginTop: 20, alignSelf: 'flex-start' }} /></View><Image source={farmerAvatar} resizeMode="cover" style={styles.farmerHeroPortrait} /></Card>
    <View style={[styles.rowWrap, desktop && { flexWrap: 'nowrap' }]}><Card style={[styles.weatherCard, { flex: 1.2 }]}><View style={styles.rowBetween}><View><Text style={styles.cardEyebrow}>{weather.location}</Text><Text style={{ color: C.ink, fontSize: 17, fontWeight: '800', marginTop: 5 }}>{weather.rain}</Text><Text style={S.muted}>Avoid spraying tomorrow afternoon</Text></View><Text style={{ fontSize: 40 }}>🌤️</Text></View><View style={styles.tempRow}><Text style={styles.temp}>{weather.temperature}°</Text><View><Text style={S.body}>{weather.condition}</Text><Text style={S.muted}>Feels like 30°</Text></View></View><Button title="View weather" secondary icon="weather-partly-cloudy" onPress={() => go('weather')} /></Card>
      <Card style={{ flex: 1, minWidth: 240 }}><View style={styles.rowBetween}><Text style={S.sectionTitle}>Farm health</Text><Tag>GOOD</Tag></View><View style={styles.healthLine}><Text style={styles.healthScore}>85</Text><Text style={{ color: C.muted, fontSize: 18 }}>/100</Text><View style={{ flex: 1, height: 10, backgroundColor: '#edf1e8', borderRadius: 9, marginLeft: 12 }}><View style={{ width: '85%', height: '100%', backgroundColor: C.green, borderRadius: 9 }} /></View></View><Text style={S.muted}>Your crop is looking healthy this week.</Text><Button title="Open farm health map" secondary icon="map-outline" onPress={() => go('map')} style={{ marginTop: 15 }} /></Card></View>
    <View style={styles.statsRow}><Stat label="Expected yield" value="4.8 t/ac" detail="↑ 8% vs last season" icon="sprout" /><Stat label="Market price" value="₹2,350" detail="per quintal · ↑ 3%" icon="currency-inr" color={C.gold} /><Stat label="Today’s tasks" value="3 / 7" detail="3 high priority" icon="clipboard-check-outline" color={C.orange} /><Stat label="Eligible schemes" value="3" detail="Support available" icon="bank-outline" color={C.blue} /></View>
    <View style={styles.rowWrap}><Card style={{ flex: 1.3 }}><View style={styles.rowBetween}><Text style={S.sectionTitle}>Today’s farm plan</Text><Pressable onPress={() => go('farm-plan')}><Text style={styles.link}>See all →</Text></Pressable></View><Text style={[S.muted, { marginTop: 4 }]}>Your most important next steps</Text><TaskPreview title="Irrigate South Field" note="Based on soil moisture data" /><TaskPreview title="Inspect for leaf spot" note="Disease risk increased nearby" /></Card>
      <Card style={{ flex: 1, minWidth: 240 }}><Text style={S.sectionTitle}>Farm copilot</Text><Text style={[S.body, { marginTop: 9 }]}>Need a hand with your crop today?</Text><Text style={[S.muted, { marginTop: 3 }]}>Ask a question by text or voice.</Text><Button title="Ask Kisaan Mitra AI" icon="microphone-outline" onPress={() => go('assistant')} style={{ marginTop: 15 }} /><Button title="Scan a crop leaf" secondary icon="camera-outline" onPress={() => go('disease')} style={{ marginTop: 9 }} /></Card></View>
    <Card><View style={styles.rowBetween}><View><Text style={S.sectionTitle}>Support for your farm</Text><Text style={S.muted}>Schemes you may qualify for</Text></View><Pressable onPress={() => go('schemes')}><Text style={styles.link}>View all →</Text></Pressable></View><View style={styles.schemeStrip}>{schemes.slice(0, 3).map(s => <View key={s.name} style={styles.schemeMini}><Text style={{ fontSize: 24 }}>{s.icon}</Text><View style={{ flex: 1 }}><Text style={styles.itemTitle}>{s.name}</Text><Text style={S.muted}>{s.amount}</Text></View><Tag>ELIGIBLE</Tag></View>)}</View></Card>
    <Card style={{ backgroundColor: '#f0f6ed' }}><View style={styles.rowBetween}><View style={{ flexDirection: 'row', gap: 10, flex: 1 }}><Icon name="lightbulb-on-outline" size={20} color={C.green} /><View style={{ flex: 1 }}><Text style={styles.itemTitle}>AI advisory</Text><Text style={S.muted}>Rain is likely tomorrow. Consider moving pesticide application to today.</Text></View></View><Button title="See alerts" secondary onPress={() => go('notifications')} /></View></Card>
  </View>;
}

function TaskPreview({ title, note }: { title: string; note: string }) { return <View style={styles.taskPreview}><View style={styles.taskBullet} /><View style={{ flex: 1 }}><Text style={styles.itemTitle}>{title}</Text><Text style={S.muted}>{note}</Text></View><Icon name="chevron-right" color={C.muted} /></View>; }

function FarmPlan({ tasks, setTasks, doneCount }: { tasks: any[]; setTasks: (t: any) => void; doneCount: number }) {
  const [tab, setTab] = useState('Tasks');
  return <View style={styles.stack}><Card><View style={styles.rowBetween}><View><Text style={S.sectionTitle}>Your plan, one step at a time</Text><Text style={S.muted}>Personalized for {farmer.crop} · {farmer.village}</Text></View><Tag>{doneCount}/{tasks.length} DONE</Tag></View><Divider /><View style={styles.segment}>{['Tasks', 'Calendar'].map(t => <Pressable key={t} onPress={() => setTab(t)} style={[styles.segmentItem, tab === t && styles.segmentActive]}><Text style={[styles.segmentText, tab === t && { color: C.greenDark }]}>{t}</Text></Pressable>)}</View>
    {tab === 'Calendar' ? <View style={{ paddingVertical: 35, alignItems: 'center' }}><Text style={{ fontSize: 32 }}>🗓️</Text><Text style={[S.sectionTitle, { marginTop: 8 }]}>Your week at a glance</Text><Text style={[S.muted, { textAlign: 'center', marginTop: 6 }]}>7 suggested tasks this week · Tap Tasks to check items off.</Text></View> : <View style={{ gap: 18, marginTop: 15 }}>{['High', 'Medium', 'Optional'].map(priority => <View key={priority}><View style={styles.priorityHeading}><Text style={styles.itemTitle}>{priority} priority</Text><Tag tone={priority === 'High' ? 'red' : priority === 'Medium' ? 'gold' : 'green'}>{tasks.filter(t => t.priority === priority && !t.done).length} TASKS</Tag></View>{tasks.filter(t => t.priority === priority).map(task => <Pressable key={task.id} onPress={() => setTasks((old: any[]) => old.map(t => t.id === task.id ? { ...t, done: !t.done } : t))} style={styles.taskRow}><Icon name={task.done ? 'checkbox-marked-circle' : 'checkbox-blank-circle-outline'} size={23} color={task.done ? C.green : priority === 'High' ? C.red : C.muted} /><View style={{ flex: 1 }}><Text style={[styles.itemTitle, task.done && { textDecorationLine: 'line-through', color: C.muted }]}>{task.title}</Text><Text style={S.muted}>{task.note}</Text></View><Icon name="chevron-right" color={C.muted} /></Pressable>)}</View>)}</View>}</Card></View>;
}

function Disease({ scanned, setScanned, go }: { scanned: boolean; setScanned: (s: boolean) => void; go: (s: string) => void }) {
  return <View style={styles.stack}><Card style={{ alignItems: 'center' }}><Image source={riceLeafPhoto} resizeMode="cover" style={styles.leafPhoto} /><Text style={[S.sectionTitle, { marginTop: 14 }]}>Take or upload a clear leaf photo</Text><Text style={[S.muted, { textAlign: 'center', maxWidth: 440, marginTop: 4 }]}>Keep the affected area in focus and use natural light for a more useful result.</Text><View style={styles.rowWrap}><Button title="Take photo" icon="camera-outline" onPress={() => setScanned(true)} style={{ flex: 1 }} /><Button title="Upload image" secondary icon="image-outline" onPress={() => setScanned(true)} style={{ flex: 1 }} /></View><Text style={[S.muted, { marginTop: 12 }]}>Example field photo · Scan actions are simulated</Text></Card>
    {scanned ? <Card><View style={styles.rowBetween}><View><Text style={S.sectionTitle}>Analysis result</Text><Text style={S.muted}>AI estimate · Example result</Text></View><Tag tone="gold">82% CONFIDENCE</Tag></View><Divider /><View style={{ flexDirection: 'row', gap: 14, alignItems: 'center' }}><Text style={{ fontSize: 35 }}>🌿</Text><View style={{ flex: 1 }}><Text style={{ color: C.red, fontSize: 17, fontWeight: '800' }}>Bacterial Leaf Blight</Text><Text style={S.muted}>Moderate severity · Paddy</Text></View></View><Text style={[S.body, { marginTop: 11 }]}>A bacterial disease affecting rice leaves. It can reduce yield if it spreads.</Text><View style={styles.adviceBox}><Text style={styles.itemTitle}>Suggested next steps</Text><Bullet text="Avoid overhead irrigation while leaves are wet." /><Bullet text="Remove badly affected leaves and monitor nearby plants." /><Bullet text="Confirm diagnosis with a local agriculture expert before treatment." /></View><Button title="Ask AI about this result" icon="robot-outline" onPress={() => go('assistant')} style={{ marginTop: 14 }} /></Card> : <Card style={{ backgroundColor: '#f0f6ed' }}><Text style={styles.itemTitle}>Good to know</Text><Text style={[S.muted, { marginTop: 4 }]}>The photo diagnosis is a guide. Confirm symptoms before applying any treatment.</Text></Card>}</View>;
}

function Bullet({ text }: { text: string }) { return <View style={{ flexDirection: 'row', gap: 8, marginTop: 9 }}><Icon name="check-circle" size={16} color={C.green} /><Text style={[S.body, { flex: 1 }]}>{text}</Text></View>; }

function WeatherScreen({ go }: { go: (s: string) => void }) {
  return <View style={styles.stack}><Card style={styles.weatherHero}><View style={styles.rowBetween}><View><Text style={{ color: '#e0f0df', fontSize: 13 }}>{weather.location}</Text><Text style={{ color: C.white, fontSize: 19, fontWeight: '800', marginTop: 9 }}>{weather.condition}</Text><Text style={{ color: C.white, fontSize: 45, fontWeight: '800' }}>{weather.temperature}°C</Text></View><Text style={{ fontSize: 65 }}>🌤️</Text></View><View style={styles.rowWrap}><View style={styles.weatherInfo}><Icon name="weather-rainy" color="#d7efd8" /><Text style={{ color: C.white, fontSize: 12 }}>Rain likely tomorrow</Text></View><View style={styles.weatherInfo}><Icon name="water-percent" color="#d7efd8" /><Text style={{ color: C.white, fontSize: 12 }}>Humidity 68%</Text></View><View style={styles.weatherInfo}><Icon name="weather-windy" color="#d7efd8" /><Text style={{ color: C.white, fontSize: 12 }}>Wind 12 km/h</Text></View></View></Card>
    <Card><Text style={S.sectionTitle}>7-day forecast</Text><Text style={[S.muted, { marginTop: 3 }]}>Example forecast · Check local conditions before field work.</Text><View style={{ marginTop: 10 }}>{weather.days.map(([day, temp, icon]) => <View key={day} style={styles.forecastRow}><Text style={[styles.itemTitle, { width: 80 }]}>{day}</Text><Text style={{ fontSize: 22, flex: 1 }}>{icon}</Text><Text style={[S.body, { width: 55, textAlign: 'right' }]}>{temp}</Text><Text style={[S.muted, { width: 90, textAlign: 'right' }]}>{day === 'Mon' || day === 'Fri' ? 'Rain likely' : 'Low chance'}</Text></View>)}</View></Card>
    <Card><Text style={S.sectionTitle}>Weather alerts</Text><AlertRow tone="red" icon="weather-pouring" title="Rain expected tomorrow" body="Avoid pesticide spraying. Secure harvested grain." /><AlertRow tone="gold" icon="weather-sunny-alert" title="High temperatures this week" body="Water crops early in the morning to reduce evaporation." /><AlertRow tone="green" icon="lightbulb-on-outline" title="Farm advisory" body="Today is a good window to apply fertilizer before the rain." /></Card><Button title="Open today’s farm plan" icon="calendar-check-outline" onPress={() => go('farm-plan')} /></View>;
}

function AlertRow({ tone, icon, title, body }: { tone: 'red' | 'gold' | 'green'; icon: string; title: string; body: string }) { const color = tone === 'red' ? C.red : tone === 'gold' ? C.orange : C.green; return <View style={styles.alertRow}><View style={[styles.alertIcon, { backgroundColor: tone === 'red' ? C.redSoft : tone === 'gold' ? '#fff5dc' : C.greenSoft }]}><Icon name={icon} size={20} color={color} /></View><View style={{ flex: 1 }}><Text style={styles.itemTitle}>{title}</Text><Text style={S.muted}>{body}</Text></View></View>; }

function MapScreen({ mode, setMode, go }: { mode: string; setMode: (s: string) => void; go: (s: string) => void }) {
  const parcels = ['#6d9d4f', '#98ae4c', '#a3bd61', '#b9a65e', '#5a984b', '#d27855', '#7fa850', '#b2ae5a', '#89a949', '#61974b', '#d17958', '#93b452'];
  return <View style={styles.stack}><Card><View style={styles.rowBetween}><View><Text style={S.sectionTitle}>Farm fields</Text><Text style={S.muted}>{farmer.village} · {farmer.area} mapped</Text></View><View style={styles.segment}>{['Map', 'Satellite'].map(v => <Pressable onPress={() => setMode(v)} key={v} style={[styles.segmentItem, mode === v && styles.segmentActive]}><Text style={[styles.segmentText, mode === v && { color: C.greenDark }]}>{v}</Text></Pressable>)}</View></View>
    <View style={styles.mapCanvas}><View style={styles.mapSky}><Text style={styles.mapPin}>📍</Text><Text style={styles.mapCaption}>SOUTH FIELD</Text>{parcels.map((color, i) => <View key={i} style={[styles.parcel, { backgroundColor: mode === 'Satellite' ? color : ['#a8d19a', '#e8d882', '#eca89a'][i % 3], transform: [{ rotate: i % 2 ? '7deg' : '-4deg' }] }]} />)}</View><View style={styles.legend}><Legend color="#6ca356" label="Healthy" /><Legend color="#d6bd64" label="Moderate stress" /><Legend color="#d6795a" label="Severe stress" /></View></View><View style={styles.rowWrap}><Stat label="Crop health" value="82%" detail="Good condition" icon="leaf" /><Stat label="Water stress" value="Low" detail="Moisture adequate" icon="water-outline" /><Stat label="Yield potential" value="High" detail="Above average" icon="chart-line" /></View><Button title="View detailed analysis" icon="chart-box-outline" onPress={() => go('yield')} /></Card><Card style={{ backgroundColor: '#f1f6ee' }}><Text style={styles.itemTitle}>About this map</Text><Text style={[S.muted, { marginTop: 4 }]}>Illustrative field map for the prototype. Satellite imagery and crop health measurements will be connected later.</Text></Card></View>;
}
function Legend({ color, label }: { color: string; label: string }) { return <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5 }}><View style={{ height: 9, width: 9, backgroundColor: color, borderRadius: 5 }} /><Text style={S.muted}>{label}</Text></View>; }

function YieldScreen({ go }: { go: (s: string) => void }) {
  return <View style={styles.stack}><Card><View style={styles.yieldBanner}><Text style={{ fontSize: 38 }}>🌾</Text><View style={{ flex: 1 }}><Text style={{ color: C.white, fontSize: 13 }}>EXPECTED PRODUCTION</Text><Text style={{ color: C.white, fontSize: 34, fontWeight: '900' }}>4.8 <Text style={{ fontSize: 15, fontWeight: '500' }}>tons / acre</Text></Text><Text style={{ color: '#dcebd8', fontSize: 12 }}>↑ 8% compared to last season</Text></View></View><View style={[styles.statsRow, { marginTop: 15 }]}><Stat label="Expected revenue" value="₹1,12,000" detail="per acre · sample estimate" icon="currency-inr" color={C.gold} /><View style={{ flex: 1, minWidth: 120 }}><Text style={styles.cardEyebrow}>YIELD RISK</Text><View style={{ height: 8, borderRadius: 6, backgroundColor: '#e7eee3', marginTop: 12 }}><View style={{ width: '24%', height: 8, borderRadius: 6, backgroundColor: C.green }} /></View><Text style={{ color: C.green, fontSize: 20, fontWeight: '800', marginTop: 5 }}>Low</Text></View></View></Card>
    <Card><Text style={S.sectionTitle}>Growth outlook</Text><Text style={S.muted}>Sample estimate across the growing season</Text><View style={styles.chartArea}><View style={styles.chartGrid}><Text style={S.muted}>5 t/ac</Text><View style={styles.chartLine} /></View><View style={styles.chartGrid}><Text style={S.muted}>3 t/ac</Text><View style={styles.chartLine} /></View><View style={styles.chartGrid}><Text style={S.muted}>1 t/ac</Text><View style={styles.chartLine} /></View><View style={styles.barChart}>{[25, 33, 42, 52, 62, 70, 84, 90].map((h, i) => <View key={i} style={[styles.bar, { height: `${h}%`, backgroundColor: i > 5 ? C.green : '#8caf7c' }]} />)}</View></View><View style={styles.rowBetween}><Text style={S.muted}>Jun</Text><Text style={S.muted}>Jul</Text><Text style={S.muted}>Aug</Text><Text style={S.muted}>Sep</Text><Text style={S.muted}>Oct</Text></View></Card>
    <Card><Text style={S.sectionTitle}>Suggestions to improve yield</Text><Bullet text="Irrigate within the next 3 days." /><Bullet text="Apply fertilizer next week, following local guidance." /><Bullet text="Monitor the field for pest activity." /><Bullet text="Maintain steady water levels during flowering." /></Card><Button title="View farm health map" icon="map-outline" onPress={() => go('map')} /></View>;
}

function MarketScreen({ go }: { go: (s: string) => void }) {
  return <View style={styles.stack}><Card><View style={styles.rowBetween}><View><Text style={S.sectionTitle}>Nearby markets</Text><Text style={S.muted}>Paddy · ₹ per quintal · sample prices</Text></View><Tag>31 OCT</Tag></View><View style={{ marginTop: 10 }}>{marketPrices.map((item, i) => <View key={item.market} style={styles.marketRow}><View style={styles.marketIcon}><Icon name="storefront-outline" size={18} color={C.green} /></View><View style={{ flex: 1 }}><Text style={styles.itemTitle}>{item.market}</Text><Text style={S.muted}>{i === 0 ? 'Best price nearby' : 'Local mandi'}</Text></View><Text style={styles.marketPrice}>₹{item.price.toLocaleString('en-IN')}</Text><Tag>{item.trend}</Tag></View>)}</View></Card>
    <Card><Text style={S.sectionTitle}>Price trend</Text><Text style={S.muted}>Last 30 days · example trend</Text><View style={styles.chartArea}><View style={styles.pricePolyline}>{[25, 34, 29, 44, 42, 58, 52, 67, 63, 78, 72, 90].map((h, i) => <View key={i} style={[styles.pricePoint, { bottom: `${h}%`, left: `${i * 8.7}%` }]} />)}</View><View style={styles.rowBetween}><Text style={S.muted}>Oct 1</Text><Text style={S.muted}>Oct 15</Text><Text style={S.muted}>Oct 31</Text></View></View><View style={styles.recommendation}><Icon name="lightbulb-on-outline" color={C.green} /><View style={{ flex: 1 }}><Text style={styles.itemTitle}>AI recommendation</Text><Text style={S.muted}>Vijayawada has the best sample price today. Compare transport costs before deciding where to sell.</Text></View></View></Card><Button title="Ask AI about selling" icon="robot-outline" onPress={() => go('assistant')} /></View>;
}

function Assistant({ chat, draft, setDraft, send }: { chat: { from: string; text: string }[]; draft: string; setDraft: (s: string) => void; send: (s?: string) => void }) {
  return <View style={styles.stack}><Card style={styles.assistantCard}><View style={styles.assistantHeader}><View style={styles.assistantAvatar}><Icon name="sprout" color={C.white} size={23} /></View><View><Text style={styles.itemTitle}>Kisaan Mitra</Text><Text style={S.muted}>Your farming assistant · Sample responses</Text></View><View style={{ flex: 1 }} /><Tag>ONLINE</Tag></View><Divider /><View style={{ gap: 13 }}>{chat.map((m, i) => <View key={i} style={[styles.chatBubble, m.from === 'farmer' ? styles.chatFarmer : styles.chatAI]}><Text style={[S.body, m.from === 'farmer' && { color: C.white }]}>{m.text}</Text></View>)}</View><Text style={[styles.inputLabel, { marginTop: 17 }]}>Suggested questions</Text><View style={styles.chips}>{['Suggest fertilizers', 'When to irrigate?', 'Today’s weather'].map((q, i) => <Pressable key={q} onPress={() => send(q)} style={styles.questionChip}><Text style={{ fontSize: 12, color: C.greenDark }}>{['🌱', '💧', '🌤️'][i]}  {q}</Text></Pressable>)}</View><View style={styles.composer}><TextInput value={draft} onChangeText={setDraft} onSubmitEditing={() => send()} placeholder="Type your question..." style={styles.composerInput} /><Pressable onPress={() => send()} style={styles.sendButton}><Icon name="arrow-up" size={20} color={C.white} /></Pressable></View><Pressable onPress={() => send('What should I do on my farm today?')} style={styles.voiceButton}><Icon name="microphone" size={24} color={C.white} /><Text style={{ color: C.white, fontWeight: '700' }}>Tap to speak (demo)</Text></Pressable></Card><Text style={S.muted}>AI responses are illustrative. Check important crop decisions with a qualified local expert.</Text></View>;
}

function Schemes() {
  const [tab, setTab] = useState('Eligible (3)');
  return <View style={styles.stack}><View style={styles.segment}>{['Eligible (3)', 'All schemes'].map(t => <Pressable key={t} onPress={() => setTab(t)} style={[styles.segmentItem, tab === t && styles.segmentActive]}><Text style={[styles.segmentText, tab === t && { color: C.greenDark }]}>{t}</Text></Pressable>)}</View>{schemes.map((scheme, i) => <Card key={scheme.name}><View style={styles.rowBetween}><View style={styles.schemeIcon}><Text style={{ fontSize: 24 }}>{scheme.icon}</Text></View><View style={{ flex: 1, marginLeft: 12 }}><Text style={styles.itemTitle}>{scheme.name}</Text><Text style={S.muted}>{scheme.detail}</Text></View><Tag>ELIGIBLE</Tag></View><Text style={{ color: C.greenDark, fontSize: 18, fontWeight: '900', marginTop: 15 }}>{scheme.amount}</Text><Button title="View application details" secondary icon="arrow-top-right" onPress={() => Alert.alert(scheme.name, 'Application details are sample content for this prototype.')} style={{ marginTop: 13 }} /></Card>)}<Card style={{ backgroundColor: '#f1f6ee' }}><Text style={styles.itemTitle}>Scheme information</Text><Text style={[S.muted, { marginTop: 5 }]}>Eligibility and benefit amounts shown here are examples. Please verify current terms with the official scheme portal or a local agriculture office.</Text></Card></View>;
}

function Notifications({ filter, setFilter }: { filter: string; setFilter: (s: string) => void }) {
  const all = [
    { type: 'Alerts', icon: 'weather-pouring', color: C.blue, title: 'Rain likely tomorrow', body: 'Avoid pesticide spraying.', time: 'Today · 8:00 AM' },
    { type: 'Schemes', icon: 'bank', color: C.orange, title: 'PM-KISAN deadline', body: 'Enrollment closes in 5 days.', time: 'Today · 7:30 AM' },
    { type: 'Alerts', icon: 'alert-outline', color: C.red, title: 'Disease risk increased', body: 'Higher probability of leaf spot nearby.', time: 'Yesterday · 6:45 PM' },
    { type: 'Alerts', icon: 'chart-line', color: C.green, title: 'Market price up', body: 'Rice price increased by 3%.', time: 'Yesterday · 5:20 PM' },
    { type: 'Tasks', icon: 'clipboard-text-outline', color: C.orange, title: 'Task reminder', body: 'Irrigate South Field.', time: 'Yesterday · 8:00 AM' },
  ];
  const options = ['All', 'Alerts', 'Tasks', 'Schemes'];
  const shown = filter === 'All' ? all : all.filter(a => a.type === filter);
  return <Card><View style={styles.segment}>{options.map(t => <Pressable key={t} onPress={() => setFilter(t)} style={[styles.segmentItem, filter === t && styles.segmentActive]}><Text style={[styles.segmentText, filter === t && { color: C.greenDark }]}>{t}</Text></Pressable>)}</View><View style={{ marginTop: 9 }}>{shown.map(item => <View key={item.title} style={styles.notificationRow}><View style={[styles.notificationIcon, { backgroundColor: `${item.color}18` }]}><Icon name={item.icon} size={20} color={item.color} /></View><View style={{ flex: 1 }}><View style={styles.rowBetween}><Text style={styles.itemTitle}>{item.title}</Text><Text style={S.muted}>{item.time}</Text></View><Text style={S.muted}>{item.body}</Text></View></View>)}</View></Card>;
}

function Community() {
  const [tab, setTab] = useState('Discussions');
  const [draft, setDraft] = useState('');
  const [posts, setPosts] = useState(discussions);
  return <View style={styles.stack}><Card><View style={styles.rowBetween}><View style={styles.segment}>{['Discussions', 'Experts'].map(t => <Pressable key={t} onPress={() => setTab(t)} style={[styles.segmentItem, tab === t && styles.segmentActive]}><Text style={[styles.segmentText, tab === t && { color: C.greenDark }]}>{t}</Text></Pressable>)}</View><Tag>{tab.toUpperCase()}</Tag></View><View style={styles.askRow}><TextInput value={draft} onChangeText={setDraft} placeholder="Ask your farming community..." style={styles.askInput} /><Pressable onPress={() => { if (draft.trim()) { setPosts([{ name: farmer.name, time: 'Just now', title: draft.trim(), body: 'Your question is now visible in this demo community.', replies: 0, initials: 'RK' }, ...posts]); setDraft(''); } }} style={styles.sendButton}><Icon name="send" color={C.white} size={18} /></Pressable></View>{posts.map(post => <View key={post.title} style={styles.discussion}><View style={styles.discussionAvatar}><Text style={{ color: C.greenDark, fontWeight: '800' }}>{post.initials}</Text></View><View style={{ flex: 1 }}><View style={styles.rowBetween}><Text style={styles.itemTitle}>{post.title}</Text><Text style={S.muted}>{post.time}</Text></View><Text style={S.muted}>{post.name} · Farmer</Text><Text style={[S.body, { marginTop: 5 }]}>{post.body}</Text><View style={{ flexDirection: 'row', gap: 17, marginTop: 8 }}><Text style={styles.link}>☏  {post.replies} replies</Text><Text style={styles.link}>♡  Like</Text></View></View></View>)}</Card>{tab === 'Experts' ? <Card style={{ backgroundColor: '#f1f6ee' }}><Text style={styles.itemTitle}>Connect with an agriculture expert</Text><Text style={[S.muted, { marginTop: 4 }]}>Expert availability and messaging will be connected in a later version.</Text></Card> : null}</View>;
}

function Profile({ go }: { go: (s: string) => void }) {
  const rows = [
    ['Farm details', 'Manage your land and farm info', 'clipboard-text-outline', 'profile-setup'],
    ['Manage crops', 'Paddy (Rice) · 10 acres', 'sprout', 'yield'], ['Farm locations', 'Anakapalle, Andhra Pradesh', 'map-marker-outline', 'map'],
    ['Notification preferences', 'Alerts, tasks and schemes', 'bell-outline', 'notifications'], ['Language', 'English', 'translate', 'profile'],
    ['Help & support', 'Get help using Kisaan Mitra', 'help-circle-outline', 'assistant'], ['About Kisaan Mitra AI', 'A farming companion for every season', 'information-outline', 'closing'],
  ];
  return <View style={styles.stack}><Card><View style={styles.profileHeader}><Image source={farmerAvatar} resizeMode="cover" style={styles.profilePhoto} /><View style={{ flex: 1 }}><Text style={S.sectionTitle}>{farmer.name}</Text><Text style={S.muted}>Farmer · {farmer.area}</Text><Text style={S.muted}>{farmer.village}, {farmer.state}</Text></View><Tag>VERIFIED</Tag></View><Divider />{rows.map(([label, detail, icon, route]) => <Pressable key={label} onPress={() => go(route)} style={styles.profileRow}><Icon name={icon} size={20} color={C.green} /><View style={{ flex: 1, marginLeft: 12 }}><Text style={styles.itemTitle}>{label}</Text><Text style={S.muted}>{detail}</Text></View><Icon name="chevron-right" color={C.muted} /></Pressable>)}</Card><Button title="Log out" secondary icon="logout" onPress={() => go('login')} /></View>;
}

function More({ go }: { go: (s: string) => void }) {
  return <View style={styles.shortcutGrid}>{menu.filter(([id]) => id !== 'dashboard').map(([id, label, icon]) => <Pressable key={id} onPress={() => go(id)} style={styles.shortcut}><View style={styles.shortcutIcon}><Icon name={icon} size={22} color={C.green} /></View><Text style={styles.itemTitle}>{label}</Text><Icon name="arrow-top-right" size={16} color={C.muted} /></Pressable>)}</View>;
}

function Closing({ go }: { go: (s: string) => void }) {
  return <View style={styles.closing}><ImageBackground source={farmerHero} resizeMode="cover" style={styles.closingPhoto} imageStyle={{ borderRadius: 20 }}><View style={styles.closingPhotoCaption}><Text style={{ color: C.white, fontWeight: '900', fontSize: 16 }}>For farmers. For a brighter tomorrow.</Text></View></ImageBackground><Text style={styles.closingTitle}>Together for a{ '\n' }better tomorrow</Text><Text style={[S.subtitle, { textAlign: 'center', maxWidth: 350, marginTop: 12 }]}>Empowering farmers with the power of AI.</Text><Button title="Keep growing with Kisaan Mitra AI" icon="arrow-right" onPress={() => go('dashboard')} style={{ width: '100%', maxWidth: 390, marginTop: 26 }} /></View>;
}

